request.description:
Connect: io('http://localhost:4001/calling')

=== CLIENT â†’ SERVER ===

register-user
  payload: { userId, userName }
  response: broadcasts 'users-online' to all clients

join-call
  payload: { callUuid, participantUuid, userName }
  â† get participantUuid from REST Join Call (step 7)
  response: 'call-joined' to caller, 'participant-joined' to others

signal  (WebRTC offer/answer/ICE)
  payload: { callUuid, signal, type, targetParticipantUuid? }
  response: forwards 'signal' to target or broadcasts to room

send-call-invitation
  payload: { targetUserId, callUuid, callType, callerId, callerName }
  response: 'incoming-call' to target, 'invitation-result' to sender

accept-call
  payload: { callUuid, callerId }
  response: 'call-accepted' to caller

reject-call
  payload: { callUuid, callerId }
  response: 'call-rejected' to caller

leave-call
  payload: { callUuid?, reason? }
  response: 'user-left-call' to room, cleanup

=== SERVER â†’ CLIENT ===

users-online        OnlineUser[]
incoming-call       { callUuid, callType, callerId, callerName }
call-accepted       { callUuid, acceptedBy, acceptedByName }
call-rejected       { callUuid, rejectedBy, rejectedByName }
call-joined         { callUuid, participants[], iceServers[] }
participant-joined  { participantUuid, userName, participantCount }
participant-left    { participantUuid, participantCount }
user-left-call      { userId, userName, reason }
signal              { fromParticipantUuid, signal, type }
invitation-result   { success, error? }
error               { message }

